function drawBackground(t){let g=ctx.createRadialGradient(W*.5,H*.48,0,W*.5,H*.48,Math.max(W,H)*.8);g.addColorStop(0,'#1a2044');g.addColorStop(.48,'#111831');g.addColorStop(1,'#080a18');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);for(const n of nebula){let a=ctx.createRadialGradient(n.x,n.y,0,n.x,n.y,n.r);a.addColorStop(0,n.c);a.addColorStop(1,'transparent');ctx.globalAlpha=n.a*(.8+Math.sin(t*.0002+n.x)*.2);ctx.fillStyle=a;ctx.fillRect(n.x-n.r,n.y-n.r,n.r*2,n.r*2)}ctx.globalAlpha=1;for(const s of stars){let tw=.45+.55*Math.sin(t*.001*s.z+s.p);ctx.globalAlpha=tw*.78;ctx.fillStyle=s.z>1.5?'#b9efff':'#a2b3e8';ctx.beginPath();ctx.arc(s.x,s.y,s.r*tw,0,TAU);ctx.fill();if(s.z>1.8){ctx.globalAlpha=tw*.2;ctx.fillRect(s.x-7,s.y,s.r*14,1)}}ctx.globalAlpha=1;}
function pathShip(x,y,scale,color='#b5fbff'){ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);ctx.shadowBlur=18;ctx.shadowColor=color;ctx.beginPath();ctx.moveTo(0,-19);ctx.lineTo(13,13);ctx.lineTo(4,9);ctx.lineTo(0,15);ctx.lineTo(-4,9);ctx.lineTo(-13,13);ctx.closePath();let grad=ctx.createLinearGradient(-10,-15,12,10);grad.addColorStop(0,'#edffff');grad.addColorStop(.45,color);grad.addColorStop(1,'#7867dd');ctx.fillStyle=grad;ctx.fill();ctx.shadowBlur=0;ctx.beginPath();ctx.moveTo(-5,12);ctx.lineTo(0,24+Math.random()*5);ctx.lineTo(5,12);ctx.fillStyle='rgba(92,233,255,.82)';ctx.fill();ctx.restore()}
function drawFoe(f,t){let c=colors[f.type],scale=Math.min(1,W/700);ctx.save();ctx.translate(f.x,f.y+Math.sin(t*.002+f.phase)*2);ctx.scale(scale,scale);ctx.shadowColor=c;ctx.shadowBlur=15;ctx.fillStyle=c;ctx.beginPath();ctx.moveTo(0,-12);ctx.lineTo(15,-3);ctx.lineTo(12,9);ctx.lineTo(5,6);ctx.lineTo(0,12);ctx.lineTo(-5,6);ctx.lineTo(-12,9);ctx.lineTo(-15,-3);ctx.closePath();ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#10142e';ctx.fillRect(-7,-3,4,3);ctx.fillRect(3,-3,4,3);ctx.fillStyle='rgba(255,255,255,.75)';ctx.fillRect(-7,-4,2,1);if(f.hp>1){ctx.fillStyle='rgba(255,255,255,.5)';ctx.fillRect(-12,-19,24,2);ctx.fillStyle=c;ctx.fillRect(-12,-19,24*f.hp/f.max,2)}ctx.restore()}
function draw(){const t=performance.now();drawBackground(t);ctx.save();if(shake>0)ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);for(const f of foes)if(f.alive)drawFoe(f,t);for(const b of shots){ctx.shadowBlur=16;ctx.shadowColor=b.color;ctx.fillStyle=b.color;ctx.beginPath();ctx.roundRect(b.x-2,b.y-10,4,13,3);ctx.fill()}for(const b of enemyShots){ctx.shadowBlur=12;ctx.shadowColor='#ff659d';ctx.fillStyle='#ff659d';ctx.beginPath();ctx.arc(b.x,b.y,b.r,0,TAU);ctx.fill()}ctx.shadowBlur=0;for(const d of drops){ctx.save();ctx.translate(d.x,d.y);ctx.rotate(d.spin);ctx.shadowBlur=19;ctx.shadowColor='#67f6ff';ctx.strokeStyle='#8cffff';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,-11);ctx.lineTo(10,0);ctx.lineTo(0,11);ctx.lineTo(-10,0);ctx.closePath();ctx.stroke();ctx.fillStyle='rgba(78,237,255,.2)';ctx.fill();ctx.rotate(-d.spin);ctx.fillStyle='#d9ffff';ctx.font='bold 11px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('↑',0,0);ctx.restore()}for(const p of particles){ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;ctx.shadowBlur=9;ctx.shadowColor=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,TAU);ctx.fill()}ctx.globalAlpha=1;ctx.shadowBlur=0;if(player){if(player.invuln<=0||Math.floor(t/95)%2===0)pathShip(player.x,player.y,1,health<30?'#ff8eaf':'#a8faff')}ctx.restore();requestAnimationFrame(draw)}
let prev=0;function loop(now){let dt=Math.min(.033,(now-prev)/1000||0);prev=now;update(dt);requestAnimationFrame(loop)}requestAnimationFrame(draw);requestAnimationFrame(loop);
})();
</script>
