 <div class="difficulty" id="difficulty"><span class="diff-label">DIFFICULTY</span><button class="diff" data-diff="calm">CALM</button><button class="diff selected" data-diff="standard">STANDARD</button><button class="diff" data-diff="intense">INTENSE</button></div>
 <div class="hud" id="hud"><div class="topbar"><div><div class="brand">STARFALL <b>// NEON UPRISING</b></div><div class="stage" id="stageName">SECTOR 01</div></div><div class="hudright"><div class="health"><div class="healthrow"><span class="statlabel">HULL INTEGRITY</span><span class="healthnum" id="healthNum">100%</span></div><div class="track"><div class="fill" id="healthFill"></div></div></div><div><div class="statlabel">SCORE</div><div class="score" id="score">000000</div></div></div></div><button class="pause" id="pause">Ⅱ &nbsp; PAUSE</button><div class="bottom"><div class="weapon"><div class="weaponicon">⌁</div><div><div class="weaponlabel">PULSE CANNON</div><div class="level">LEVEL <em id="weaponLevel">01</em><span style="color:#7886aa"> / 10</span></div></div></div><div class="hint"><kbd>←</kbd> <kbd>→</kbd> MOVE &nbsp; <kbd>SPACE</kbd> FIRE &nbsp; <kbd>ESC</kbd> PAUSE</div></div><div class="progress"><i id="progress"></i></div></div>
 <div class="screen hidden" id="modal"><div class="modalcard"><div class="eyebrow" id="modalEye">SIGNAL LOST</div><h2 id="modalTitle">Hull breached</h2><p id="modalText"></p><button class="primary" id="modalPrimary">REDEPLOY ↗</button><button class="secondary" id="modalSecondary">RETURN TO MENU</button></div></div><div class="toast" id="toast">WEAPON UPGRADED</div>
 <div class="touch" id="touch"><div class="touchgroup"><button data-move="-1">←</button><button data-move="1">→</button></div><div class="touchgroup"><button id="fire">✦</button></div></div>
+<script>
+(()=>{
+const canvas=document.querySelector('#universe'),ctx=canvas.getContext('2d'),$=id=>document.getElementById(id),hud=$('hud'),menu=$('menu'),modal=$('modal'),difficulty=$('difficulty'),TAU=Math.PI*2;
+let W=innerWidth,H=innerHeight,DPR=1,stars=[],clouds=[],scene='menu',diff='standard',score=0,stage=1,level=1,health=100,shots=[],foes=[],enemyShots=[],drops=[],parts=[],player=null,formation=1,fireWait=0,spawnWait=0,kills=0,dropsStage=0,keys={},touchDir=0,firing=false,toastTime=0,shake=0;
+const maxStages=15,colors=['#68f3ff','#ff6ebc','#ae83ff','#ffbf70'],names=['THE FIRST LIGHT','DUST & ECHOES','VIOLET FRONTIER','THE RED VEIL','BROKEN ORBIT','GHOST SIGNAL','STARFORGE','DARK MATTER','NOVA RUN','THE LONG NIGHT','ION STORM','LAST TRANSMISSION','BLACK SUN','THE SWARM','HOMEWARD'],settings={calm:{speed:.72,damage:12,foe:1.05},standard:{speed:1,damage:19,foe:1.35},intense:{speed:1.32,damage:28,foe:1.72}};
+function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*DPR;canvas.height=H*DPR;canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(DPR,0,0,DPR,0,0);stars=Array.from({length:Math.floor(W*H/4200)},()=>({x:Math.random()*W,y:Math.random()*H,z:Math.random()*2+.25,r:Math.random()*1.25+.25,p:Math.random()*TAU}));clouds=Array.from({length:7},()=>({x:Math.random()*W,y:Math.random()*H,r:Math.random()*170+80,c:colors[Math.random()*4|0],a:Math.random()*.045+.016}));if(player)player.y=H*.83}addEventListener('resize',resize);resize();
+function start(){score=0;stage=1;level=1;health=100;begin();menu.classList.add('hidden');difficulty.classList.add('hidden');modal.classList.add('hidden');hud.classList.add('active');scene='playing'}
+function begin(){shots=[];foes=[];enemyShots=[];drops=[];parts=[];kills=0;dropsStage=0;formation=1;fireWait=0;player={x:W/2,y:H*.83,speed:Math.max(260,W*.43),invuln:1.3};let rows=Math.min(3+Math.floor((stage-1)/5),5),cols=Math.min(6+Math.floor((stage-1)/3),10),space=Math.min(68,W/(cols+1));for(let r=0;r<rows;r++)for(let c=0;c<cols;c++){let hp=stage>5&&Math.random()<.23?2:1;foes.push({x:W/2+(c-(cols-1)/2)*space,y:Math.max(90,H*.17)+r*48,hp,max:hp,phase:Math.random()*TAU,type:(r+c+stage)%4,alive:true})}spawnWait=.5;$('stageName').textContent=`SECTOR ${String(stage).padStart(2,'0')} · ${names[stage-1]}`;ui()}
+function ui(){$('score').textContent=String(score).padStart(6,'0');$('healthNum').textContent=Math.max(0,Math.ceil(health))+'%';$('healthFill').style.width=Math.max(0,health)+'%';$('weaponLevel').textContent=String(level).padStart(2,'0');$('progress').style.width=(stage-1+Math.min(1,kills/Math.max(1,foes.length)))/maxStages*100+'%'}
+function showModal(title,text,button,action,eye='SIGNAL LOST'){scene='modal';modal.classList.remove('hidden');$('modalTitle').textContent=title;$('modalText').textContent=text;$('modalPrimary').textContent=button+' ↗';$('modalEye').textContent=eye;$('modalPrimary').onclick=action;$('modalSecondary').onclick=()=>{scene='menu';modal.classList.add('hidden');hud.classList.remove('active');menu.classList.remove('hidden');difficulty.classList.remove('hidden');$('best').textContent=String(+(localStorage.getItem('starfallBest')||0)).padStart(6,'0')}}
+function pause(){if(scene==='playing')showModal('Hold position','The stars can wait. Your run is safely paused.','RESUME',()=>{modal.classList.add('hidden');scene='playing'},'FLIGHT PAUSED')}
+function finish(){let best=Math.max(score,+(localStorage.getItem('starfallBest')||0));localStorage.setItem('starfallBest',best);$('best').textContent=String(best).padStart(6,'0');showModal('Hull breached',`You reached sector ${String(stage).padStart(2,'0')} with ${score.toLocaleString()} points. Your weapon dropped to level ${Math.max(1,level-1)}.`,'REDEPLOY',()=>{level=Math.max(1,level-1);health=100;begin();modal.classList.add('hidden');scene='playing'})}
+$('best').textContent=String(+(localStorage.getItem('starfallBest')||0)).padStart(6,'0');$('start').onclick=start;$('pause').onclick=pause;document.querySelectorAll('.diff').forEach(b=>b.onclick=()=>{diff=b.dataset.diff;document.querySelectorAll('.diff').forEach(x=>x.classList.toggle('selected',x===b))});
+addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight',' ','ArrowUp','ArrowDown'].includes(e.key))e.preventDefault();keys[e.key.toLowerCase()]=true;if(e.key==='Escape'&&scene==='playing')pause();if(e.key==='Enter'&&scene==='menu')start()});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
+document.querySelectorAll('[data-move]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();touchDir=+b.dataset.move;b.setPointerCapture(e.pointerId)};['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,()=>touchDir=0))});$('fire').onpointerdown=e=>{e.preventDefault();firing=true};['pointerup','pointercancel','lostpointercapture'].forEach(ev=>$('fire').addEventListener(ev,()=>firing=false));
+function burst(x,y,color,n=8){for(let i=0;i<n;i++){let a=Math.random()*TAU,s=Math.random()*180+35;parts.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.35+Math.random()*.5,max:.85,color,r:Math.random()*2.5+1})}}
+function toast(text){$('toast').textContent=text;$('toast').classList.add('show');toastTime=1.6}
+function shoot(){let spread=Math.min(2,Math.floor((level-1)/3));for(let i=-spread;i<=spread;i++)shots.push({x:player.x+i*13,y:player.y-18,vy:-650,damage:1+Math.floor((level-1)/4),color:i?'#8c8dff':'#9bfbff'})}
+function drop(x,y){if(dropsStage<3){dropsStage++;drops.push({x,y,vy:95,r:12,spin:Math.random()*TAU})}}
+function hitPlayer(){if(player.invuln>0)return;health-=settings[diff].damage;player.invuln=1.05;shake=9;burst(player.x,player.y,'#ff679f',18);ui();if(health<=0){health=0;ui();finish()}}

input.newString:
if(health<=0){health=0;ui();finish()}}
function update(dt){if(scene!=='playing')return;player.invuln=Math.max(0,player.invuln-dt);let dir=(keys.arrowleft||keys.a?-1:0)+(keys.arrowright||keys.d?1:0)+touchDir;player.x=Math.max(25,Math.min(W-25,player.x+dir*player.speed*settings[diff].speed*dt));if((keys[' ']||keys.w||keys.arrowup||firing)&&fireWait<=0){shoot();fireWait=Math.max(.105,.28-(level-1)*.014)}fireWait-=dt;
let alive=foes.filter(f=>f.alive),move=30+stage*5;for(const f of alive){f.phase+=dt*2;f.x+=formation*move*settings[diff].foe*dt;f.y+=Math.sin(f.phase)*dt*5}if(alive.some(f=>f.x>W-25||f.x<25)){formation*=-1;for(const f of alive)f.y+=12+stage*.4}
spawnWait-=dt;if(spawnWait<=0&&alive.length){let f=alive[Math.random()*alive.length|0];enemyShots.push({x:f.x,y:f.y+15,vy:190+stage*8,r:4});spawnWait=Math.max(.3,1.25-stage*.035)*(Math.random()*.7+.65)/settings[diff].foe}
